Definition stateless_input_sub_slice {base : Z} {source_len : Z}
(s : StatelessInputSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && ((0 <=? source_len) && ((base + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: StatelessInputSliceFields (base + off) len :=
   {| StatelessInputSliceFields_bytes := Z.add base (off);  StatelessInputSliceFields_len := len |}.

Definition scratch_sub_slice {base : Z} {source_len : Z}
(s : ScratchSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && ((0 <=? source_len) && ((base + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: ScratchSliceFields (base + off) len :=
   {| ScratchSliceFields_bytes := Z.add base (off);  ScratchSliceFields_len := len |}.

Definition memory_sub_slice {base : Z} {source_len : Z}
(s : EvmMemorySliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && ((0 <=? source_len) && ((base + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: EvmMemorySliceFields (base + off) len :=
   {| EvmMemorySliceFields_bytes := Z.add base (off);  EvmMemorySliceFields_len := len |}.

Definition log_data_sub_slice {base : Z} {source_len : Z}
(s : LogDataSliceFields base source_len) (off : Z) (len : Z)
(*(0 <=? base) && ((0 <=? source_len) && ((base + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? off) && ((0 <=? len) && ((off + len) <=? source_len)))*)
: LogDataSliceFields (base + off) len :=
   {| LogDataSliceFields_bytes := Z.add base (off);  LogDataSliceFields_len := len |}.

Definition calldata_sub_slice (s : CalldataSlice) (off : Z) (len : Z)
(*(0 <=? off) && (off <=? (2 ^ 32 - 1)) && ((0 <=? len) && (len <=? (2 ^ 32 - 1)))*)
: M (CalldataSlice) :=
   match s with
   | InputCalldata (@existT _ _ syn_len (@existT _ _ syn_off bytes)) =>
      (if Z.leb ((Z.add (off) (len))) (bytes.(StatelessInputSliceFields_len)) then
         let subslice := stateless_input_sub_slice (bytes) (off) (len) in
         returnM ((InputCalldata (@existT _ _ _ (@existT _ _ _ (subslice)))))
       else assert_exp' false "calldata sub-slice bounds" >>= fun _ => exit tt)
       : M (CalldataSlice)
   | MemoryCalldata (@existT _ _ syn_len (@existT _ _ syn_off bytes)) =>
      (if Z.leb ((Z.add (off) (len))) (bytes.(EvmMemorySliceFields_len)) then
         let subslice := memory_sub_slice (bytes) (off) (len) in
         returnM ((MemoryCalldata (@existT _ _ _ (@existT _ _ _ (subslice)))))
       else assert_exp' false "calldata sub-slice bounds" >>= fun _ => exit tt)
       : M (CalldataSlice)
   end
    : M (CalldataSlice).

Definition stateless_input_slice_suffix {base : Z} {source_len : Z}
(s : StatelessInputSliceFields base source_len) (off : Z)
(*(0 <=? base) && ((0 <=? source_len) && ((base + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? off) && (off <=? source_len))*)
: StatelessInputSliceFields (base + off) (source_len - off) :=
   {| StatelessInputSliceFields_bytes := Z.add base (off);
      StatelessInputSliceFields_len := Z.sub source_len (off) |}.

Definition scratch_slice_suffix {base : Z} {source_len : Z}
(s : ScratchSliceFields base source_len) (off : Z)
(*(0 <=? base) && ((0 <=? source_len) && ((base + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? off) && (off <=? source_len))*)
: ScratchSliceFields (base + off) (source_len - off) :=
   {| ScratchSliceFields_bytes := Z.add base (off);
      ScratchSliceFields_len := Z.sub source_len (off) |}.

Definition undefined_ExceptionKind '(tt : unit) : M (ExceptionKind) :=
   (internal_pick
      ([StackUnderflow;
      StackOverflow;
      OutOfGas;
      InvalidOpcode;
      InvalidJump;
      StaticViolation;
      CallDepthExceeded;
      InsufficientBalance;
      WriteProtection;
