(tx : StatelessInputSliceFields ex552553_ ex552554_)
(pubkey : StatelessInputSliceFields ex552557_ ex552558_) (sender : vec (mword 8) 20)
(fields : StatelessInputSliceFields source_off source_len)
(*(0 <=? source_off) && ((0 <=? source_len) && ((source_off + source_len) <=? (2 ^ 32 - 1)))*)
(*(0 <=? ex552553_) && ((0 <=? ex552554_) && ((ex552553_ + ex552554_) <=? (2 ^ 32 - 1))) &&
  ((0 <=? ex552554_) && (ex552554_ <=? (2 ^ 30)))*)
(*(0 <=? ex552557_) && ((0 <=? ex552558_) && ((ex552557_ + ex552558_) <=? (2 ^ 32 - 1)))*)
: M (TransactionFields 0) :=
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 chain_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (chain_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 nonce_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (nonce_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 mp_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (mp_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 mf_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (mf_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 gas_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (gas_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 to_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (to_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 value_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (value_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 data_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (data_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 al_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (al_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 auth_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (auth_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 v_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (v_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 r_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (r_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __chain_f1 (@existT _ _ __chain_f0 s_f)) =>
   let fields :=
     rlp_cursor_advance (fields) (s_f.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_cursor_expect_end (fields)) >>
   ((rlp_decode_word (v_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun v =>
   (decode_access_list (al_f)) >>= fun access_list =>
   (decode_auth_list (auth_f)) >>= fun '(@existT _ _ __authorizations authorizations) =>
   ((rlp_decode_uint64 (nonce_f)) >>= fun semanticResult =>
    returnM (semanticResult).(ssz_uint_value)) >>= fun decoded_nonce =>
   let nonce :=
     (word_of_account_nonce (Build_account_nonce ((decoded_nonce)))).(account_nonce_value) in
   ((rlp_decode_word (to_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun recipient_word =>
   let recipient := word_to_address (Build_word ((recipient_word))) in
   let '(@existT _ _ signing_span__'len (@existT _ _ signing_span__'off signing_span)) :=
     (tx_sig_span (chain_f) (v_f) : {len & {off & (StatelessInputSliceFields off len)}}%type) in
   (tx_signing_hash (SetCodeTx) (signing_span) (Build_word ((v)))) >>= fun signing_hash =>
   ((rlp_decode_uint64 (chain_f)) >>= fun semanticResult =>
    returnM (semanticResult).(ssz_uint_value)) >>= fun (w__0 : Z) =>
   ((rlp_decode_gas (gas_f)) >>= fun semanticResult =>
    returnM (semanticResult).(transaction_gas_value)) >>= fun (w__1 : Z) =>
   ((rlp_decode_u256 (value_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (w__2 : Z) =>
   (tx_input_span (data_f)) >>= fun '(@existT _ _ __w__31 (@existT _ _ __w__30 w__3)) =>
   ((rlp_decode_u256 (mf_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (w__4 : Z) =>
   ((rlp_decode_u256 (mp_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (w__5 : Z) =>
   ((rlp_decode_u256 (r_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (w__6 : Z) =>
   ((rlp_decode_u256 (s_f)) >>= fun semanticResult => returnM (semanticResult).(word_value)) >>= fun (w__7 : Z) =>
   returnM (({| TransactionFields_tx_type := SetCodeTx;
                TransactionFields_sender := sender;
                TransactionFields_raw :=
                  @existT _ _ ex552554_ (@existT _ _ ex552553_ ((tx : StatelessInputSliceFields ex552553_ ex552554_)));
                TransactionFields_nonce := (Build_word (nonce));
                TransactionFields_chain_id := (Build_chain_identifier (w__0));
                TransactionFields_gas_limit := (Build_transaction_gas (w__1));
                TransactionFields_is_create := Z.eqb (to_f.(RlpFieldRef_content_len)) (0);
                TransactionFields_recipient := recipient;
                TransactionFields_value := (Build_word (w__2));
                TransactionFields_input_src := @existT _ _ _ (@existT _ _ _ (w__3));
                TransactionFields_access_list := access_list;
                TransactionFields_max_fee := (Build_word (w__4));
                TransactionFields_max_blob_fee := (Build_word ((ZERO_WORD).(word_value)));
                TransactionFields_max_priority_fee := (Build_word (w__5));
                TransactionFields_authorizations := @existT _ _ _ (authorizations);
                TransactionFields_blob_hashes := EMPTY_BLOB_HASHES;
                TransactionFields_pubkey :=
                  @existT _ _ ex552558_ (@existT _ _ ex552557_ ((pubkey : StatelessInputSliceFields ex552557_ ex552558_)));
                TransactionFields_signing_hash := signing_hash;
                TransactionFields_sig_v := (Build_word (v));
                TransactionFields_sig_r := (Build_word (w__6));
                TransactionFields_sig_s := (Build_word (w__7)) |})).

Definition rlp_decode_tx {tx_off : Z} {tx_len : Z} {public_key_off : Z}
(tx : StatelessInputSliceFields tx_off tx_len)
(pubkey : StatelessInputSliceFields public_key_off 65) (blob_limit : Z)
(*(0 <=? tx_off) && ((0 <=? tx_len) && ((tx_off + tx_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? tx_len) &&
    ((tx_len <=? (2 ^ 30)) &&
      ((0 <=? public_key_off) && ((0 <=? 65) && ((public_key_off + 65) <=? (2 ^ 32 - 1))) &&
        ((blob_limit =? 0) || ((blob_limit =? 6) || (blob_limit =? 9))))))*)
: M (Transaction) :=
   let public_key_body := stateless_input_sub_slice (pubkey) (1) (PUBLIC_KEY_BODY_LENGTH) in
   (stateless_input_keccak256
      (@existT _ _ 64 (@existT _ _ (public_key_off + 1) ((public_key_body : StatelessInputSliceFields (public_key_off + 1) 64))))) >>= fun public_key_hash =>
   let public_key_word := (hash_to_word (public_key_hash)).(word_value) in
   let sender := word_to_address (Build_word ((public_key_word))) in
   let tx_length := tx.(StatelessInputSliceFields_len) in
   (if Z.eqb tx_len (0) return M (mword 8) then (fatal_error (RlpDecode))  : M (mword 8)
    else (stateless_input_slice_byte (tx) (0))  : M (mword 8)) >>= fun (b0 : mword 8) =>
   let ttype : mword 8 :=
     if eq_vec ((subrange_vec_dec (b0) (7) (6))) (('b"11")) then (Ox"00")
     else b0 in
   let typed := neq_vec (ttype) ((Ox"00")) in
   (if typed return M (TransactionInputSlice) then
      (if Z.leb (1) tx_len then
         returnM ((@existT _ _ (tx_len - 1) (@existT _ _ (tx_off + 1) ((stateless_input_sub_slice
                                                                          (tx) (1)
                                                                          ((Z.sub tx_len (1))) : StatelessInputSliceFields (tx_off + 1) (tx_len - 1))))) : {len & {off & (StatelessInputSliceFields off len)}}%type)
       else (fatal_error (RlpDecode))  : M (TransactionInputSlice))
       : M (TransactionInputSlice)
    else
      returnM ((@existT _ _ tx_len (@existT _ _ tx_off ((tx : StatelessInputSliceFields tx_off tx_len)))) : TransactionInputSlice)) >>= fun '(@existT _ _ __payload1 (@existT _ _ __payload0 payload)) =>
   let '(@existT _ _ payload_input__'len (@existT _ _ payload_input__'off payload_input)) :=
     (@existT _ _ _ (@existT _ _ _ (payload)) : StatelessInputSlice) in
   (rlp_node_cursor (payload_input)) >>= fun '(@existT _ _ __fields1 (@existT _ _ __fields0 fields)) =>
   let p0_ := ttype in
   (if eq_vec (p0_) ((Ox"00")) then returnM (LegacyTx)
    else if eq_vec (p0_) ((Ox"01")) then returnM (AccessListTx)
    else if eq_vec (p0_) ((Ox"02")) then returnM (FeeMarketTx)
    else if eq_vec (p0_) ((Ox"03")) then returnM (BlobTx)
    else if eq_vec (p0_) ((Ox"04")) then returnM (SetCodeTx)
    else (fatal_error (RlpDecode))  : M (TxType)) >>= fun (tx_type : TxType) =>
   match tx_type with
   | LegacyTx =>
      (decode_legacy_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | AccessListTx =>
      (decode_access_list_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | FeeMarketTx =>
      (decode_fee_market_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | BlobTx =>
      (decode_blob_tx (tx) (pubkey) (blob_limit) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   | SetCodeTx =>
      (decode_set_code_tx (tx) (pubkey) (sender) (fields)) >>= fun decoded =>
      returnM ((pack_transaction (decoded)) : {syn_blob_limit & (TransactionFields syn_blob_limit)}%type)
   end
    : M ({syn_blob_limit & (TransactionFields syn_blob_limit)}%type).

