Definition undefined_EnvField '(tt : unit) : M (EnvField) :=
   (internal_pick
      ([F_Number;
      F_Timestamp;
      F_Coinbase;
      F_BaseFee;
      F_ChainId;
      F_GasLimit;
      F_PrevRandao;
      F_Origin;
      F_GasPrice;
      F_SlotNumber]))
    : M (EnvField).

Definition k_env (f : EnvField) : M (word) :=
   (read_reg k_tx >>= fun '(@existT _ _ __active_tx active_tx) =>
   match f with
   | F_Number =>
      read_reg k_header >>= fun (w__0 : BlockHeader) =>
      let number :=
        (word_of_block_number
           (Build_block_number (((w__0.(BlockHeader_number)).(block_number_value))))).(block_number_value) in
      returnM (((u256 (number)).(word_value)))
   | F_Timestamp =>
      read_reg k_header >>= fun (w__1 : BlockHeader) =>
      let timestamp :=
        (word_of_block_timestamp
           (Build_block_timestamp (((w__1.(BlockHeader_timestamp)).(block_timestamp_value))))).(block_timestamp_value) in
      returnM (((u256 (timestamp)).(word_value)))
   | F_Coinbase =>
      read_reg k_header >>= fun (w__2 : BlockHeader) =>
      returnM (((address_to_word (w__2.(BlockHeader_fee_recipient))).(word_value)))
   | F_BaseFee =>
      read_reg k_header >>= fun (w__3 : BlockHeader) =>
      returnM ((w__3.(BlockHeader_base_fee)).(word_value))
   | F_ChainId =>
      (read_reg k_chain_id) >>= fun semanticResult =>
      returnM (semanticResult).(chain_identifier_value) >>= fun (w__4 : Z) =>
      let chain_id :=
        (word_of_chain_identifier (Build_chain_identifier ((w__4)))).(chain_identifier_value) in
      returnM (((u256 (chain_id)).(word_value)))
   | F_GasLimit =>
      read_reg k_header >>= fun (w__5 : BlockHeader) =>
      returnM (((u256 ((w__5.(BlockHeader_gas_limit)).(block_gas_limit_value))).(word_value)))
   | F_PrevRandao =>
      read_reg k_header >>= fun (w__6 : BlockHeader) =>
      returnM ((w__6.(BlockHeader_prev_randao)).(word_value))
   | F_Origin => returnM (((address_to_word (active_tx.(TxEnvFields_origin))).(word_value)))
   | F_GasPrice => returnM ((active_tx.(TxEnvFields_gas_price)).(word_value))
   | F_SlotNumber =>
      read_reg k_header >>= fun (w__7 : BlockHeader) =>
      let slot_number :=
        (word_of_slot_number
           (Build_slot_number_typ (((w__7.(BlockHeader_slot_number)).(slot_number_value))))).(slot_number_value) in
      returnM (((u256 (slot_number)).(word_value)))
   end
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

Definition k_coinbase '(tt : unit) : M (address_typ) :=
   read_reg k_header >>= fun (w__0 : BlockHeader) => returnM (w__0.(BlockHeader_fee_recipient)).

Definition blockhash_word_distance (current : Z) (number : Z)
(*(0 <=? number) && ((number <? current) && (current <? (2 ^ 256)))*)
: Z :=
   Z.sub (current) (number).

Definition k_blockhash (number_word : word)
(*(0 <=? number_word) && (number_word <=? (2 ^ 256 - 1))*)
: M (hash) :=
   let number_word := (number_word).(word_value) in
   read_reg k_header >>= fun (w__0 : BlockHeader) =>
   let current := (w__0.(BlockHeader_number)).(block_number_value) in
   let current_number :=
     (word_of_block_number (Build_block_number ((current)))).(block_number_value) in
   let current_word : Z := (u256 (current_number)).(word_value) in
   (if Z.ltb (number_word) (current_word) return M (vec (mword 8) 32) then
      let distance_word := blockhash_word_distance (current_word) (number_word) in
      (if Z.leb (distance_word) (256) return M (vec (mword 8) 32) then
         let distance : Z := distance_word in
         (read_reg k_n_headers) >>= fun semanticResult =>
         returnM (semanticResult).(ancestor_hash_count_value) >>= fun (w__1 : Z) =>
         (if Z.ltb (w__1) (distance) return M (vec (mword 8) 32) then
            (fatal_error (WitnessDeficient))
             : M (vec (mword 8) 32)
          else
            let index : Z := Z.sub (distance) (1) in
            (ancestor_hash_read (Build_ancestor_index ((index))))
             : M (vec (mword 8) 32))
          : M (vec (mword 8) 32)
       else returnM (ZERO_HASH))
       : M (vec (mword 8) 32)
    else returnM (ZERO_HASH))
    : M (vec (mword 8) 32).

Definition k_blobhash (index_word : word) (*(0 <=? index_word) && (index_word <=? (2 ^ 256 - 1))*)
: M (word) :=
   let index_word := (index_word).(word_value) in
   (read_reg k_tx >>= fun '(@existT _ _ __active_tx active_tx) =>
   let count := active_tx.(TxEnvFields_blob_hashes).(BlobHashesFields_count) in
   (if Z.ltb (index_word) (count) return M (Z) then
      let index := index_word in
      let offset : Z := Z.add ((Z.mul (33) (index))) (1) in
      ((stateless_input_slice_load_n
          (projT2 (projT2 (active_tx.(TxEnvFields_blob_hashes).(BlobHashesFields_bytes)))) (offset)
          (WORD_BYTE_LENGTH)) >>= fun semanticResult =>
       returnM (semanticResult).(word_value))
       : M (Z)
    else returnM ((ZERO_WORD).(word_value)))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_word (semanticResult)).

