    : M (NodeRef).

Fixpoint _rec_decode_input_branch_node {source_off : Z} {source_len : Z}
(cursor : StatelessInputSliceFields source_off source_len) (index : Z) (children : vec NodeRef 16)
(_reclimit : Z)
(*(0 <=? source_off) && ((0 <=? source_len) && ((source_off + source_len) <=? (2 ^ 32 - 1)))*)
(*(2 <=? index) && (index <=? 16)*) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (InputTrieNode).
