   assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
   (if Z.ltb (index) (16) return M (InputTrieNode) then
      (rlp_decode_item (cursor)) >>= fun '(@existT _ _ __child1 (@existT _ _ __child0 child)) =>
      let next :=
