      (input_field_to_ref (child)) >>= fun decoded_child =>
      let updated := children in
      let updated : vec NodeRef 16 := vec_update_dec (updated) (index) (decoded_child) in
      (_rec_decode_input_branch_node _ _ (next) ((Z.add (index) (1))) (updated)
         ((Z.sub (_reclimit) (1))) (_limit_reduces_bool _acc ltac:(assumption)))
       : M (InputTrieNode)
    else
      (rlp_decode_item (cursor)) >>= fun '(@existT _ _ __value1 (@existT _ _ __value0 value)) =>
      let next :=
        rlp_cursor_advance (cursor) (value.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
      (rlp_cursor_expect_end (next)) >>
      let '(@existT _ _ content__'len (@existT _ _ content__'off content)) :=
        (rlp_item_content (value) : {len & {off & (StatelessInputSliceFields off len)}}%type) in
      returnM ((InputBranchNode ((children, @existT _ _ _ (@existT _ _ _ (content)))))))
    : M (InputTrieNode)
).
Defined.


Definition decode_input_branch_node {source_off : Z} {source_len : Z}
