Definition path_empty '(tt : unit) : TriePath := path_new (ZERO_HASH) (Build_trie_path_len ((0))).

Definition HEX_PREFIX_MAX_LENGTH : Z := 33.
#[export] Hint Unfold HEX_PREFIX_MAX_LENGTH : sail.
Definition hex_prefix_decode_ref {source_off : Z} {source_len : Z} {content_len : Z}
(f : RlpFieldRef source_off source_len content_len)
(*(0 <=? source_off) && ((0 <=? source_len) && ((source_off + source_len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? content_len) && (content_len <=? source_len))*)
: M ((bool * TriePath)) :=
   (if f.(RlpFieldRef_is_list) return M (unit) then (fatal_error (RlpDecode))  : M (unit)
    else returnM (tt)) >>
   let n := f.(RlpFieldRef_content_len) in
   (if Z.eqb content_len (0) then returnM ((false, path_empty (tt)))
    else
      let maximum_length := HEX_PREFIX_MAX_LENGTH in
      (if Z.ltb (maximum_length) content_len return M ((bool * TriePath)) then
         (fatal_error (RlpDecode))
          : M ((bool * TriePath))
       else
         let content :=
           stateless_input_sub_slice (f.(RlpFieldRef_source)) ((Z.sub source_len content_len))
             content_len in
         (stateless_input_slice_byte (content) (0)) >>= fun fb =>
         let flag : mword 4 := subrange_vec_dec (fb) (7) (4) in
         let is_leaf : bool := eq_vec ((access_vec_dec (flag) (1))) (('b"1")) in
         let odd : bool := eq_vec ((access_vec_dec (flag) (0))) (('b"1")) in
         let tail_length : Z := Z.sub content_len (1) in
         let tail := stateless_input_slice_suffix (content) (1) in
         ((stateless_input_slice_load (tail) (0)) >>= fun semanticResult =>
          returnM (semanticResult).(word_value)) >>= fun packed =>
         let paired_nibbles : Z := Z.mul (tail_length) (2) in
         (if odd return M ((bool * TriePath)) then
            (if Z.ltb (paired_nibbles) (64) then
               let shifted :=
                 (word_shift_right (Build_word ((packed))) (Build_word_bit_count ((4)))).(word_value) in
               let bytes := word_to_hash (Build_word ((shifted))) in
               let bytes : vec (mword 8) 32 :=
                 vec_update_dec (bytes) (0)
                   ((concat_vec ((subrange_vec_dec (fb) (3) (0)))
                       ((subrange_vec_dec ((vec_access_dec (bytes) (0))) (3) (0))))) in
               let path_data := B256 (bytes) in
               let path :=
                 path_new (path_data) (Build_trie_path_len (((Z.add (paired_nibbles) (1))))) in
               returnM ((is_leaf, path))
             else (fatal_error (WitnessDeficient))  : M ((bool * TriePath)))
             : M ((bool * TriePath))
          else
            let path_data := word_to_hash (Build_word ((packed))) in
            let path := path_new (path_data) (Build_trie_path_len ((paired_nibbles))) in
            returnM ((is_leaf, path)))
          : M ((bool * TriePath)))
       : M ((bool * TriePath)))
    : M ((bool * TriePath)).

Definition path_len (path : TriePath) : trie_path_len :=
   (Build_trie_path_len ((path.(TriePath_len)).(trie_path_len_value))).

Definition decode_input_trie_node {ex552800_ : Z} {ex552799_ : Z}
(node : StatelessInputSliceFields ex552799_ ex552800_)
(*(0 <=? ex552799_) && ((0 <=? ex552800_) && ((ex552799_ + ex552800_) <=? (2 ^ 32 - 1)))*)
: M (InputTrieNode) :=
   (if Z.eqb (node.(StatelessInputSliceFields_len)) (0) return M (unit) then
      (fatal_error (RlpDecode))
       : M (unit)
    else returnM (tt)) >>
   (rlp_node_cursor (node)) >>= fun '(@existT _ _ __fields1 (@existT _ _ __fields0 fields)) =>
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __first1 (@existT _ _ __first0 first)) =>
   let fields :=
     rlp_cursor_advance (fields) (first.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (rlp_decode_item (fields)) >>= fun '(@existT _ _ __first1 (@existT _ _ __first0 second)) =>
   let fields :=
     rlp_cursor_advance (fields) (second.(RlpFieldRef_source).(StatelessInputSliceFields_len)) in
   (if Z.eqb (fields.(StatelessInputSliceFields_len)) (0) return M (InputTrieNode) then
      (hex_prefix_decode_ref (first)) >>= fun '((is_leaf, path)) =>
      (if is_leaf then
         let '(@existT _ _ value__'len (@existT _ _ value__'off value)) :=
           (rlp_item_content (second) : {len & {off & (StatelessInputSliceFields off len)}}%type) in
         returnM ((InputLeafNode ((path, @existT _ _ _ (@existT _ _ _ (value))))))
       else
         let path_length := (path_len (path)).(trie_path_len_value) in
         (if Z.eqb (path_length) (0) return M (InputTrieNode) then
            (fatal_error (RlpDecode))
             : M (InputTrieNode)
          else
            (input_field_to_ref (second)) >>= fun child =>
            returnM ((InputExtensionNode ((path, child)))))
          : M (InputTrieNode))
       : M (InputTrieNode)
    else
      let empty_child := EmptyRef (tt) in
      (input_field_to_ref (first)) >>= fun first_child =>
      (input_field_to_ref (second)) >>= fun second_child =>
      let children : vec NodeRef 16 := vector_init (16) (empty_child) in
      let children : vec NodeRef 16 := vec_update_dec (children) (0) (first_child) in
      let children : vec NodeRef 16 := vec_update_dec (children) (1) (second_child) in
      (decode_input_branch_node (fields) (2) (children))
       : M (InputTrieNode))
    : M (InputTrieNode).

Definition path_byte_index (i : trie_path_cursor) (*(0 <=? i) && (i <=? 64)*) : M (b256_index) :=
   let i := (i).(trie_path_cursor_value) in
   (let quotient := Z.quot (i) (2) in
   (if andb ((Z.leb (0) (quotient))) ((Z.leb (quotient) (31))) then returnM (quotient)
    else assert_exp' false "sail/lib/mpt/primitives.sail:45.24-45.25" >>= fun _ => exit tt)
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_b256_index (semanticResult)).

Definition path_nibble (path : TriePath) (i : trie_path_cursor) (*(0 <=? i) && (i <=? 64)*)
: M (nibble) :=
   let i := (i).(trie_path_cursor_value) in
   let length := (path_len (path)).(trie_path_len_value) in
   (if Z.leb (length) (i) then returnM ((Ox"0"))
    else
      let bytes := path.(TriePath_data) in
      ((path_byte_index (Build_trie_path_cursor ((i)))) >>= fun semanticResult =>
       returnM (semanticResult).(b256_index_value)) >>= fun byte_index =>
      let parity := Z.rem (i) (2) in
      returnM ((if Z.eqb (parity) (0) then
                  subrange_vec_dec ((vec_access_dec (bytes) (byte_index))) (7) (4)
                else subrange_vec_dec ((vec_access_dec (bytes) (byte_index))) (3) (0))))
    : M (mword 4).

Definition path_matches (key : TriePath) (pos : trie_path_cursor) (seg : TriePath)
(*(0 <=? pos) && (pos <=? 64)*)
: M (bool) :=
   let pos := (pos).(trie_path_cursor_value) in
   let segment_len := (path_len (seg)).(trie_path_len_value) in
   let key_len := (path_len (key)).(trie_path_len_value) in
   let stop := Z.add (pos) (segment_len) in
   (if Z.ltb (key_len) (stop) then returnM (false)
    else
      let ok : bool := true in
      let offset : Z := 0 in
      (whileMT
        (offset, ok)
        (fun '(offset, ok) => Z.sub (segment_len) (offset))
        (fun '(offset, ok) => returnM ((andb (ok) (((Z.ltb (offset) (segment_len))  : bool)))))
        (fun '(offset, ok) =>
          (assert_exp' true "loop dummy assert" >>= fun _ =>
           let key_index := Z.add (pos) (offset) in
           (if Z.leb (key_index) (64) return M (bool) then
              (path_nibble (key) (Build_trie_path_cursor ((key_index)))) >>= fun key_nibble =>
              (path_nibble (seg) (Build_trie_path_cursor ((offset)))) >>= fun segment_nibble =>
              let ok : bool :=
                if neq_vec (key_nibble) (segment_nibble) then
                  let ok : bool := false in
                  ok
                else ok in
              returnM (ok)
            else returnM (false)) >>= fun (ok : bool) =>
           let current_offset := offset in
           (if Z.ltb (current_offset) (64) then returnM ((Z.add (current_offset) (1)))
            else (fatal_error (WitnessDeficient))  : M (Z)) >>= fun (w__1 : Z) =>
           let offset := w__1  : Z in
           returnM ((offset, ok)))
           : M ((Z * bool)))) >>= fun '((offset, ok)
      : (Z * bool)) =>
      returnM (ok))
    : M (bool).

Definition resolve_witness_ref (r : NodeRef) : M (StatelessInputSlice) :=
   match r with
   | EmptyRef tt =>
      returnM ((@existT _ _ 0 (@existT _ _ 0 ((EMPTY_STATELESS_INPUT_SLICE : StatelessInputSliceFields 0 0)))) : {len & {off & (StatelessInputSliceFields off len)}}%type)
   | InputInlineRef (@existT _ _ len (@existT _ _ off node)) =>
      returnM ((@existT _ _ _ (@existT _ _ _ (node))) : {len & {off & (StatelessInputSliceFields off len)}}%type)
   | ScratchInlineRef _ =>
      (fatal_error (WitnessDeficient))
       : M ({len & {off & (StatelessInputSliceFields off len)}}%type)
   | HashRef h =>
