                                (early_return (GAS_CHARGE_UNAFFORDABLE
                                 : GasCharge) :
                                  MR GasCharge Z)
                                 : MR (GasCharge) (Z)
                              else
                                returnR (GasCharge) ((Z.add ((Z.mul (16) (bounded_extra)))
                                                        (high_bits))))
                              : MR (GasCharge) (Z)
                           else
                             let pre_osaka_limit := Z.add ((Z.mul (3) (available))) (2) in
                             let extra_limit : Z := 0 in
                             let extra_limit : Z := e_div (pre_osaka_limit) (8) in
                             let extra_unaffordable := Z.gtb (extra) (extra_limit) in
                             let bounded_extra : Z :=
                               if extra_unaffordable then extra_limit
                               else extra in
                             (if extra_unaffordable return MR (GasCharge) (Z) then
                                (early_return (GAS_CHARGE_UNAFFORDABLE
                                 : GasCharge) :
                                  MR GasCharge Z)
                                 : MR (GasCharge) (Z)
                              else
                                returnR (GasCharge) ((Z.add ((Z.mul (8) (bounded_extra)))
                                                        (high_bits))))
                              : MR (GasCharge) (Z)) >>= fun (count : Z) =>
                          returnR (GasCharge) ((if Z.eqb (count) (0) then 1 else count))) >>= fun (iterations : Z) =>
                       returnR (GasCharge) ((if Z.eqb (iterations) (0) then GAS_CHARGE_UNAFFORDABLE
                                             else
                                               let product : Z := Z.mul (mult) (iterations) in
                                               let product_unaffordable :=
                                                 Z.ltb (wide_product_limit) (product) in
                                               let affordable_product : Z :=
                                                 if product_unaffordable then product_limit
                                                 else product in
                                               if product_unaffordable then GAS_CHARGE_UNAFFORDABLE
                                               else
                                                 let calculated :=
                                                   if osaka then affordable_product
                                                   else e_div (affordable_product) (3) in
                                                 let cost :=
                                                   if Z.ltb (calculated) (minimum) then minimum
                                                   else calculated in
                                                 if Z.leb (cost) (available) then
                                                   let affordable : Z := cost in
                                                   gas_charge (Build_gas_cost ((affordable)))
                                                 else GAS_CHARGE_UNAFFORDABLE)))
                     : MR (GasCharge) (GasCharge))
                  : MR (GasCharge) (GasCharge))
               : MR (GasCharge) (GasCharge))
            : MR (GasCharge) (GasCharge))
         : MR (GasCharge) (GasCharge))
      : MR (GasCharge) (GasCharge)).

