Definition legacy_sstore_costs (original : word) (current : word) (new_value : word) (cold : bool)
(*(0 <=? original) && (original <=? (2 ^ 256 - 1))*)
(*(0 <=? current) && (current <=? (2 ^ 256 - 1))*)
(*(0 <=? new_value) && (new_value <=? (2 ^ 256 - 1))*)
: M (SstoreCosts) :=
   let original := (original).(word_value) in
   let current := (current).(word_value) in
   let new_value := (new_value).(word_value) in
   let cold_cost : Z :=
     if cold then (G_cold_sload).(gas_constant_value)
     else (GAS_CONSTANT_ZERO).(gas_constant_value) in
   ((sstore_clear_refund (tt)) >>= fun semanticResult =>
    returnM (semanticResult).(gas_constant_value)) >>= fun (clear_refund : Z) =>
   let clean_change := andb ((neq_int (current) (new_value))) ((Z.eqb (original) (current))) in
   let original_is_zero := word_is_zero (original) in
   let current_is_zero := word_is_zero (current) in
   let new_value_is_zero := word_is_zero (new_value) in
   let original_is_nonzero := negb (original_is_zero) in
   let base : Z :=
     if clean_change then
       if original_is_zero then (G_sset).(gas_constant_value)
       else (G_sreset).(gas_constant_value)
     else (G_warm_access).(gas_constant_value) in
   let refund : Z :=
     if Z.eqb (current) (new_value) then 0
     else if Z.eqb (original) (current) then
       if andb (original_is_nonzero) (new_value_is_zero) then clear_refund
       else 0
     else
       let clear_delta :=
         if original_is_zero then 0
         else
           let withdrawn_clear_refund := if current_is_zero then Z.sub (0) (clear_refund) else 0 in
           let awarded_clear_refund := if new_value_is_zero then clear_refund else 0 in
           Z.add (withdrawn_clear_refund) (awarded_clear_refund) in
       let reset_delta :=
         if Z.eqb (original) (new_value) then
           if original_is_zero then
             Z.sub ((G_sset).(gas_constant_value)) ((G_warm_access).(gas_constant_value))
           else Z.sub ((G_sreset).(gas_constant_value)) ((G_warm_access).(gas_constant_value))
         else 0 in
       Z.add (clear_delta) (reset_delta) in
   returnM (({| SstoreCosts_execution := (Build_gas_cost (Z.add (base) (cold_cost)));
                SstoreCosts_refund := (Build_gas_refund (refund));
                SstoreCosts_state_charge := (Build_gas_cost (0));
                SstoreCosts_state_credit := (Build_state_gas_spill (0)) |})).

Definition amsterdam_sstore_costs
(original : word) (current : word) (new_value : word) (cold : bool)
(*(0 <=? original) && (original <=? (2 ^ 256 - 1))*)
(*(0 <=? current) && (current <=? (2 ^ 256 - 1))*)
(*(0 <=? new_value) && (new_value <=? (2 ^ 256 - 1))*)
: SstoreCosts :=
   let original := (original).(word_value) in
   let current := (current).(word_value) in
   let new_value := (new_value).(word_value) in
   let changed := neq_int (current) (new_value) in
   let clean_change := andb ((Z.eqb (original) (current))) (changed) in
   let access := (amsterdam_storage_access_cost (cold)).(gas_constant_value) in
   let original_is_zero := word_is_zero (original) in
   let current_is_zero := word_is_zero (current) in
   let new_value_is_zero := word_is_zero (new_value) in
   let original_is_nonzero := negb (original_is_zero) in
   let current_is_nonzero := negb (current_is_zero) in
   let execution : Z :=
     if clean_change then Z.add (access) ((G_amsterdam_storage_write).(gas_constant_value))
     else access in
   let clear_delta : Z :=
     if andb (changed)
          ((andb (original_is_nonzero) ((andb (current_is_nonzero) (new_value_is_zero))))) then
       R_amsterdam_storage_clear
     else if andb (changed) ((andb (original_is_nonzero) (current_is_zero))) then
       Z.sub (0) (R_amsterdam_storage_clear)
     else 0 in
   let restore_delta :=
     if andb (changed) ((Z.eqb (original) (new_value))) then
       (G_amsterdam_storage_write).(gas_constant_value)
     else 0 in
   let refund : Z := Z.add (clear_delta) (restore_delta) in
   let state_charge : Z :=
     if andb (clean_change) (original_is_zero) then
       (G_amsterdam_state_storage_set).(state_gas_spill_value)
     else (GAS_COST_ZERO).(gas_cost_value) in
   let state_credit : Z := 0 in
   let state_credit : Z :=
     if andb (changed) ((andb ((Z.eqb (original) (new_value))) (original_is_zero))) then
       let state_credit : Z := (G_amsterdam_state_storage_set).(state_gas_spill_value) in
       state_credit
     else state_credit in
   {| SstoreCosts_execution := (Build_gas_cost (execution));
      SstoreCosts_refund := (Build_gas_refund (refund));
      SstoreCosts_state_charge := (Build_gas_cost (state_charge));
      SstoreCosts_state_credit := (Build_state_gas_spill (state_credit)) |}.

Definition sstore_costs (original : word) (current : word) (new_value : word) (cold : bool)
(*(0 <=? original) && (original <=? (2 ^ 256 - 1))*)
(*(0 <=? current) && (current <=? (2 ^ 256 - 1))*)
(*(0 <=? new_value) && (new_value <=? (2 ^ 256 - 1))*)
: M (SstoreCosts) :=
   let original := (original).(word_value) in
   let current := (current).(word_value) in
   let new_value := (new_value).(word_value) in
   read_reg k_execution_profile >>= fun '(@existT _ _ __execution_profile12 (@existT _ _ __execution_profile11 (@existT _ _ __execution_profile10 (@existT _ _ __execution_profile9 (@existT _ _ __execution_profile8 (@existT _ _ __execution_profile7 (@existT _ _ __execution_profile6 (@existT _ _ __execution_profile5 (@existT _ _ __execution_profile4 (@existT _ _ __execution_profile3 (@existT _ _ __execution_profile2 (@existT _ _ __execution_profile1 (@existT _ _ __execution_profile0 execution_profile))))))))))))) =>
   let profile := execution_profile.(ExecutionProfileFields_protocol) in
   (if Z.geb (profile.(ProtocolProfileFields_fork)) (Amsterdam) then
      returnM ((amsterdam_sstore_costs (Build_word ((original))) (Build_word ((current)))
                  (Build_word ((new_value))) (cold)))
    else
      (legacy_sstore_costs (Build_word ((original))) (Build_word ((current)))
         (Build_word ((new_value))) (cold))
       : M (SstoreCosts))
    : M (SstoreCosts).

Definition word_scaled_gas_cost (per_unit : gas_constant) (units : word) (available : gas_typ)
(*(0 <=? per_unit) && (per_unit <=? 45000)*) (*(0 <=? units) && (units <=? (2 ^ 256 - 1))*)
(*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let per_unit := (per_unit).(gas_constant_value) in
   let units := (units).(word_value) in
   let available := (available).(gas_value) in
   if orb ((Z.eqb (per_unit) (0))) ((Z.eqb (units) (0))) then
     gas_charge (Build_gas_cost (((GAS_COST_ZERO).(gas_cost_value))))
   else if Z.leb (units) (available) then
     let affordable_units : Z := units in
     let exact_cost : Z := Z.mul (per_unit) (affordable_units) in
     if Z.leb (exact_cost) (available) then
       let cost : Z := exact_cost in
       gas_charge (Build_gas_cost ((cost)))
     else GAS_CHARGE_UNAFFORDABLE
   else GAS_CHARGE_UNAFFORDABLE.

Definition memory_word_gas_cost
(base : gas_constant) (per_word : gas_constant) (size : word) (available : gas_typ)
(*(0 <=? base) && (base <=? 45000)*) (*(0 <=? per_word) && (per_word <=? 45000)*)
(*(0 <=? size) && (size <=? (2 ^ 256 - 1))*) (*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let base := (base).(gas_constant_value) in
   let per_word := (per_word).(gas_constant_value) in
   let size := (size).(word_value) in
   let available := (available).(gas_value) in
   if Z.gtb (base) (available) then GAS_CHARGE_UNAFFORDABLE
   else
     let after_base : Z := Z.sub (available) (base) in
     let words := (memory_word_count_word (Build_word ((size)))).(word_value) in
     let variable :=
       word_scaled_gas_cost (Build_gas_constant ((per_word))) (Build_word ((words)))
         (Build_gas_typ ((after_base))) in
     if variable.(GasCharge_affordable) then
       let exact_cost : Z := Z.add (base) ((variable.(GasCharge_cost)).(gas_cost_value)) in
       if Z.leb (exact_cost) (available) then
         let cost : Z := exact_cost in
         gas_charge (Build_gas_cost ((cost)))
       else GAS_CHARGE_UNAFFORDABLE
     else GAS_CHARGE_UNAFFORDABLE.

Definition keccak_gas_cost (size : word) (available : gas_typ)
(*(0 <=? size) && (size <=? (2 ^ 256 - 1))*) (*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let size := (size).(word_value) in
   let available := (available).(gas_value) in
   memory_word_gas_cost (Build_gas_constant (((G_keccak).(gas_constant_value))))
     (Build_gas_constant ((G_keccak_word))) (Build_word ((size))) (Build_gas_typ ((available))).

Definition copy_gas_cost (size : word) (available : gas_typ)
(*(0 <=? size) && (size <=? (2 ^ 256 - 1))*) (*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let size := (size).(word_value) in
   let available := (available).(gas_value) in
