     (Build_gas_constant (((G_copy_word).(gas_constant_value)))) (Build_word ((size)))
     (Build_gas_typ ((available))).

Definition log_gas_cost (num_topics : log_topic_count) (size : word) (available : gas_typ)
(*(0 <=? num_topics) && (num_topics <=? 4)*) (*(0 <=? size) && (size <=? (2 ^ 256 - 1))*)
(*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let num_topics := (num_topics).(log_topic_count_value) in
