      let item_length := BN254_PAIRING_ITEM_LENGTH in
      (if Z.eqb (input_length) ((Z.mul ((e_div (input_length) (item_length))) (item_length)))
         return
         M (PrecompileResult) then
         ((accelerator_bn254_pairing (input)) >>= fun semanticResult =>
          returnM (semanticResult).(pairing_check_result_value)) >>= fun result =>
         (pairing_result (Build_pairing_check_result ((result))))
          : M (PrecompileResult)
