Definition encode_state_account (info : AccountInfo) (storage_root : vec (mword 8) 32)
: M (ScratchSlice) :=
   let nonce_length := rlp_uint_word_size ((info.(AccountInfo_nonce)).(account_nonce_value)) in
   let balance_length := rlp_uint_word_size ((info.(AccountInfo_balance)).(word_value)) in
   let storage_root_length := rlp_word_size (tt) in
   let code_hash_length := rlp_word_size (tt) in
   let content_len :=
     Z.add ((Z.add ((Z.add (nonce_length) (balance_length))) (storage_root_length)))
       (code_hash_length) in
   (rlp_list_size (content_len)) >>= fun encoded_length =>
   (rlp_encoder_begin (encoded_length)) >>= fun encoder =>
   (rlp_write_list_prefix (content_len)) >>
   (rlp_write_uint_word ((info.(AccountInfo_nonce)).(account_nonce_value))) >>
   (rlp_write_uint_word ((info.(AccountInfo_balance)).(word_value))) >>
   let storage_root_word := (hash_to_word (storage_root)).(word_value) in
   (rlp_write_word (Build_word ((storage_root_word)))) >>
   let code_hash_word := (hash_to_word (info.(AccountInfo_code_hash))).(word_value) in
   (rlp_write_word (Build_word ((code_hash_word)))) >>
   (rlp_encoder_finish (encoder))
    : M ({len & {off & (ScratchSliceFields off len)}}%type).

