(*(0 <=? source_off) && ((0 <=? source_len) && ((source_off + source_len) <=? (2 ^ 32 - 1)))*)
: M (Z) :=
   (_rec_bal_validate_accounts (cursor) ((cursor.(StatelessInputSliceFields_len)  : Z))
      (Zwf_guarded _))
    : M (Z).

Definition validate_block_access_list {ex555349_ : Z} {ex555348_ : Z}
(bytes : StatelessInputSliceFields ex555348_ ex555349_) (block_gas_limit : block_gas_limit)
(*(0 <=? ex555348_) && ((0 <=? ex555349_) && ((ex555348_ + ex555349_) <=? (2 ^ 32 - 1))) &&
  ((0 <=? (2 ^ 30)) && (ex555349_ <=? (2 ^ 30)))*)
(*(0 <=? block_gas_limit) && (block_gas_limit <=? (2 ^ 64 - 1))*)
: M (unit) :=
   let block_gas_limit := (block_gas_limit).(block_gas_limit_value) in
   (bal_prepare_iter (tt)) >>
   (rlp_single_ref (bytes)) >>= fun '(@existT _ _ __root root) =>
   (bal_ref_cursor (root)) >>= fun accounts_cursor =>
   (bal_validate_accounts (accounts_cursor)) >>= fun bal_items =>
   (bal_iter_next (tt)) >>= fun remaining_event =>
   match remaining_event with
   | BalEmpty _ => returnM (tt)
   | _ => (fatal_error (InvalidBlockAccessList))  : M (unit)
   end >>
   (if Z.gtb ((Z.mul (BLOCK_ACCESS_LIST_ITEM_GAS) (bal_items))) (block_gas_limit)
      return
      M (unit) then
      (fatal_error (BlockAccessListTooLarge))
       : M (unit)
    else returnM (tt))
    : M (unit).

Definition block_gas_usage_empty (_limit : Z) (*(0 <=? _limit) && (_limit <=? (2 ^ 64 - 1))*)
: BlockGasUsageFields _limit 0 0 0 :=
   {| BlockGasUsageFields_execution := 0;
      BlockGasUsageFields_state := 0;
      BlockGasUsageFields_receipts := 0 |}.

Definition block_gas_usage_add {limit : Z} {execution : Z} {state : Z} {receipts : Z}
(usage : BlockGasUsageFields limit execution state receipts) (add_execution : Z) (add_state : Z)
(add_receipt : Z)
(*(0 <=? limit) &&
  ((limit <=? (2 ^ 64 - 1)) &&
    ((0 <=? execution) &&
      ((execution <=? limit) &&
        ((0 <=? state) &&
          ((state <=? limit) && ((0 <=? receipts) && (receipts <=? (execution + state)))))))) &&
  ((0 <=? add_execution) &&
    ((add_execution <=? (limit - execution)) &&
      ((0 <=? add_state) &&
        ((add_state <=? (limit - state)) &&
          ((0 <=? add_receipt) && (add_receipt <=? (add_execution + add_state)))))))*)
: BlockGasUsageFields limit (execution + add_execution) (state + add_state) (receipts + add_receipt) :=
   {| BlockGasUsageFields_execution := Z.add execution (add_execution);
      BlockGasUsageFields_state := Z.add state (add_state);
      BlockGasUsageFields_receipts := Z.add receipts (add_receipt) |}.

